/** Largest-first, and — critically — a two-pass design: compute the plan,
 *  and only commit it if the full amount can be met. A partial dispense is
 *  worse than a refusal. */
final class CashDispenser {
    private final int[] denominations;   // descending
    private final int[] counts;

    Optional<int[]> plan(int amount) {
        int[] take = new int[denominations.length];

        for (int i = 0; i < denominations.length && amount > 0; i++) {
            int wanted = amount / denominations[i];
            take[i] = Math.min(wanted, counts[i]);
            amount -= take[i] * denominations[i];
        }

        // Nothing has been touched yet. If we cannot make it exactly, we say
        // so and the hopper is untouched.
        return amount == 0 ? Optional.of(take) : Optional.empty();
    }

    void commit(int[] take) {
        for (int i = 0; i < counts.length; i++) counts[i] -= take[i];
    }
}

/** Coin-change DP over a bounded supply. O(amount x denominations) time.
 *  Reach for this only when the interviewer says the denominations are
 *  arbitrary, or asks for provably fewest notes. */
int fewestNotes(int amount, int[] denoms, int[] counts) {
    int[] best = new int[amount + 1];
    Arrays.fill(best, Integer.MAX_VALUE);
    best[0] = 0;

    for (int d = 0; d < denoms.length; d++) {
        for (int used = 1; used <= counts[d]; used++) {          // bounded supply
            for (int a = amount; a >= denoms[d]; a--) {
                if (best[a - denoms[d]] != Integer.MAX_VALUE) {
                    best[a] = Math.min(best[a], best[a - denoms[d]] + 1);
                }
            }
        }
    }
    return best[amount] == Integer.MAX_VALUE ? -1 : best[amount];
}
